  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Chat dengan model pilihanmu; {mnemo} membaca, menulis, memberi tag, menautkan, memindahkan, dan merapikan catatan dengan alat bawaan Memora. Ia tidak bisa menjelajah web, menjalankan perintah, menghapus permanen, atau mengubah server. Kunci disegel di server ini dan tidak pernah dikirim ke browser.",
