  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude dan ChatGPT masuk dengan akun Memora-mu. Tidak ada yang perlu disalin.",
  "Claude models": "Model Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude masuk lewat OAuth, jadi tidak ada kunci yang ditempel: ia mendapat kuncinya sendiri saat kamu menekan Allow. Tanpa masuk, hubungkan sebagai <b>Aplikasi lain</b> dan kirim header <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor, dan lainnya",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor, dan lainnya, masing-masing dengan kuncinya sendiri",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex, dan lainnya masing-masing mendapat akses sendiri, jadi kamu bisa melihat apa yang dilakukan tiap AI.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT, dan agen buatanmu berbagi satu Memora, yang bisa diakses dari komputer ini, jaringan lokal, atau internet",
  "Claude, Cursor, ChatGPT and your own scripts read your notes and add to them.": "Claude, Cursor, ChatGPT, dan skrip buatanmu membaca catatanmu dan menambahkan isinya.",
