  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "Chat yang dihapus beserta pesannya hilang permanen. Catatanmu tidak tersentuh, dan chat yang sedang menjawab dibiarkan.",
  "Deleted notes": "Catatan terhapus",
  "Deleted notes wait here until you restore them or delete them forever. When you restore, you choose where the note goes: its old folder, another folder or the top level.": "Catatan yang dihapus menunggu di sini sampai kamu memulihkan atau menghapusnya permanen. Saat memulihkan, kamu pilih tujuannya: folder lamanya, folder lain, atau tingkat atas.",
