  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Seret kartu ke bingkai folder lain untuk memindah catatan di disk. Seret bingkai lewat namanya untuk menata papan; jatuhkan ke bingkai lain untuk memindah seluruh folder ke sana. Klik dua kali judul untuk mengganti nama. Di layar sentuh: seret untuk menggeser, cubit untuk zoom, tekan lama kartu untuk memindahnya, ketuk untuk pratinjau.",
  "Drag a note here to pin it": "Seret catatan ke sini untuk menyematkannya",
  "Drag notes or folders here to pin them": "Seret catatan atau folder ke sini untuk menyematkannya",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Seret catatan atau folder ke sebuah folder untuk memindahkannya, ke Disematkan untuk menyematkannya.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Seret catatan · klik dua kali untuk sematkan · / cari · #tag cari tag · F muatkan · 1 2 3 tata letak",
  "Drag to move the folder frame; double-click to rename": "Seret untuk memindah bingkai folder; klik dua kali untuk mengganti nama",
  "Drag to move the lane. Double click the name to rename it.": "Seret untuk memindahkan kolom. Klik dua kali namanya untuk mengganti nama.",
  "Drag to resize · double-click to reset": "Seret untuk mengubah ukuran · klik dua kali untuk mengatur ulang",
  "Drag to turn · scroll to zoom · click a point to open its note": "Seret untuk memutar · gulir untuk zoom · klik titik untuk membuka catatannya",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Seret untuk memutar · gulir untuk zoom · klik titik untuk membuka catatannya · / untuk mencari · #tag cari tag",
  "Draw a chart of how many notes I write each week": "Buat grafik jumlah catatan yang kutulis tiap minggu",
