  "Dyslexic": "Disleksia",
  "Each AI app connects over MCP with its own key and permissions.": "Setiap aplikasi AI terhubung lewat MCP dengan kunci dan izinnya sendiri.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Setiap aplikasi AI yang kamu hubungkan adalah agen dengan key sendiri, jadi kamu bisa melihat apa yang dilakukan masing-masing dan mematikannya sendiri-sendiri.",
  "Each agent": "Tiap agen",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Setiap agen milik satu aplikasi. Untuk aplikasi atau perangkat lain, buat agen baru.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Setiap agen milik satu aplikasi. Untuk memakai Memora di aplikasi lain, buat agen terpisah.",
  "Each app gets its own key": "Setiap aplikasi punya kuncinya sendiri",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Masing-masing punya ID pendek yang tidak pernah berubah, jadi namanya bebas diganti. Mnemo menyiapkan, mengubah instruksi atau model, mengirim pesan, menunggu, menghentikan, menyelesaikan, dan menghapus mereka, satu per satu atau sekaligus, serta bisa membiarkan mereka bekerja di latar belakang. Setiap kartu menampilkan Instruksi, Aktivitas, dan Jawaban.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Setiap jenis diukur terhadap ruangnya sendiri: batasnya jika diatur, atau pemakaiannya ditambah ruang disk kosong{disk}. Batas kosong: tanpa batas.",
  "Each one gets its own key from Memora.": "Masing-masing mendapat kunci sendiri dari Memora.",
