  "Embed in a note…": "Sematkan ke catatan…",
  "Embed new or existing boards in a note and work on each right there, or put a board into any note from its ⋯ menu; a plain link reads as a small card.": "Sematkan papan baru atau yang sudah ada ke catatan dan kerjakan langsung di sana, atau taruh papan ke catatan mana pun lewat menu ⋯; tautan biasa tampil sebagai kartu kecil.",
