  "Enter your password": "Masukkan kata sandimu",
  "Entries": "Entri",
  "Error": "Galat",
  "Error 404": "Galat 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "Meski dipakai setiap hari, browser harus masuk lagi setelah selama ini. Tidak boleh lebih pendek dari waktu tidak aktif.",
  "Every AI loses {n} tool at once. Asks first.": "Semua AI langsung kehilangan {n} tool. Ditanya dulu.",
  "Every AI loses {n} tools at once. Asks first.": "Semua AI langsung kehilangan {n} tool. Ditanya dulu.",
  "Every Kanban board in your notes": "Semua papan Kanban di catatanmu",
  "Every action, newest first": "Semua aksi, terbaru dulu",
  "Every action, newest first, with search and filters.": "Semua aksi, terbaru dulu, dengan pencarian dan filter.",
  "Every address from one to another.": "Semua alamat dari satu ke yang lain.",
  "Every address from the first to the last, joined by a dash.": "Semua alamat dari awal sampai akhir, dipisah tanda hubung.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Biasanya setiap agen mulai dari nol. {bold} hubungkan tiap agen sekali dan semuanya membaca vault yang sama serta menulis kembali ke sana, jadi apa yang dipelajari satu agen bisa dipakai yang lain.",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "Setiap papan dengan kolom dan kemajuannya. Papan baru ada di mana pun Catatan baru berada: sidebar, Ringkasan, folder, menu, pencarian, dan tombol B.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Semua browser dan agen terputus sampai seseorang menyalakan Memora lagi di mesin itu. Halaman ini tidak bisa menyalakannya lagi.",
  "Every call shows up live in the brain and Activity": "Setiap panggilan tampil langsung di brain dan Aktivitas",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Setiap perubahan dari Mnemo tampil di Aktivitas dan bisa dibatalkan dari Riwayat.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Setiap perubahan, olehmu atau oleh aplikasi, tampil di Aktivitas dan bisa dibatalkan dari Riwayat.",
  "Every chat is archived.": "Semua chat sudah diarsipkan.",
  "Every chat with your notes agent": "Semua chat dengan agen catatan Anda",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Semua AI yang terhubung langsung kehilangan {n} tool dan tidak bisa membaca atau mengubah catatanmu sampai kamu menyalakan tool lagi di sini.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Semua AI yang terhubung langsung kehilangannya. Kamu bisa menyalakannya lagi kapan saja.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Semua AI yang terhubung langsung kehilangannya. Kamu bisa menyalakannya lagi kapan saja.",
  "Every connected agent loses its memory until Memora runs again.": "Setiap agen yang terhubung kehilangan memorinya sampai Memora berjalan lagi.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Semua perangkat di jaringan rumah atau kantor, ditulis alamat/ukuran: 192.168.1.0/24 mencakup 192.168.1.0 sampai 192.168.1.255.",
  "Every device on a home or office network.": "Semua perangkat di jaringan rumah atau kantor.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Semua gambar di folder catatan dan di mana ditampilkan, serta gambar yang disimpan untuk chat Mnemo.",
  "Every image is used in a note.": "Semua gambar dipakai di catatan.",
  "Every note": "Semua catatan",
  "Every note and link, in 3D, as a graph or on a board.": "Setiap catatan dan tautan, dalam 3D, sebagai graf, atau di papan.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Semua catatan dan subfolder di \"{path}\" dipindah ke {folder}; lalu \"{name}\" dihapus. Jika nama sudah dipakai di sana, akan ditambahkan angka.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Setiap catatan menjadi kartu di sini, di dalam bingkai foldernya. Panduan menunjukkan cara meminta AI menyimpan pengetahuannya di sini, atau tulis catatan sendiri.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Setiap catatan menjadi titik cahaya di sini, dikelompokkan per folder. Panduan menunjukkan cara meminta AI menyimpan pengetahuannya di sini, atau tulis catatan sendiri.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Setiap catatan bertag #{tag} ({notes}) mendapat nama baru, termasuk #tag di dalam teks.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Setiap catatan bertag {tags} mendapat satu tag sebagai gantinya ({notes}). #tag di dalam teks juga berubah. Tidak ada undo sekali klik; setiap catatan tetap menyimpan riwayatnya.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Setiap baca dan tulis oleh agen muncul langsung, jadi kamu selalu tahu siapa melakukan apa.",
  "Every request that reaches this rule is {verb}.": "Setiap permintaan yang sampai ke aturan ini {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Semua permintaan. Taruh paling akhir untuk menangkap yang tidak kena aturan di atas.",
  "Every setting and where it lives.": "Semua pengaturan dan tempatnya.",
  "Every shortcut in the web UI.": "Semua pintasan di UI web.",
  "Every tag and its notes": "Semua tag dan catatannya",
  "Every tool agents can call": "Semua alat yang bisa dipanggil agen",
