  "Font": "Font",
  "For": "Untuk",
  "For authentication choose <b>OAuth</b>, leave the client ID and secret empty, and click <b>Create</b>. A Memora page opens: press <b>Allow</b>.": "Untuk autentikasi pilih <b>OAuth</b>, biarkan client ID dan secret kosong, lalu klik <b>Create</b>. Halaman Memora terbuka: tekan <b>Allow</b>.",
