  "From now on, whenever I tell you something important, save it into Memora. Try it now: save a note that I started using Memora today.": "Mulai sekarang, setiap kali aku memberitahumu hal penting, simpan ke Memora. Coba sekarang: simpan catatan bahwa aku mulai memakai Memora hari ini.",
