  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "Mengumpulkan aktivitas sebenarnya untuk {range}. Ini bisa makan waktu di log besar, mohon tunggu.",
  "General": "Umum",
  "Get a one-time code on the server": "Dapatkan kode sekali pakai di server",
  "Get started": "Mulai",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Kenali aku dari catatanku. Telusuri vault-ku (catatan terbaru, jurnal, proyek, apa pun tentang aku) dan simpan yang kamu pelajari dengan remember_owner: siapa aku, apa yang kukerjakan, jawaban seperti apa yang kusuka, apa yang kusuka. Hanya hal singkat yang tahan lama, jangan pernah rahasia. Lalu ceritakan dalam beberapa baris apa yang kamu simpan.",
  "Gets its own agent key: read and write nodes over MCP": "Mendapat kunci agen sendiri: baca dan tulis node lewat MCP",
  "Getting started": "Memulai",
  "GitHub answered HTTP {code}": "GitHub menjawab HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Beri Claude, Cursor, atau aplikasi MCP apa pun key sendiri, lalu biarkan ia menyimpan apa yang sudah diketahuinya tentangmu.",
  "Give a key read-only access, or let it write too.": "Beri kunci akses hanya baca, atau izinkan juga menulis.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Beri setiap aplikasi atau perangkat agennya sendiri. Aktivitas lalu menunjukkan persis siapa melakukan apa, dan kamu bisa mematikan satu tanpa mengganggu yang lain.",
  "Give it a name you recognise": "Beri nama yang kamu kenali",
  "Give the agent a name": "Beri nama agennya",
