  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "Seberapa banyak ruang yang dipakai catatan, gambar, dan chat Mnemo, masing-masing terhadap ruangnya sendiri. Spanduk memperingatkan saat salah satunya hampir penuh.",
