  "Identity": "Identitas",
  "Idle": "Siaga",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Kalau Memora berguna buatmu, kasih star di GitHub atau cerita ke teman bikin orang lain ikut menemukannya. Kalau tidak, ya tidak apa-apa.",
  "If you leave, they are kept on this device and offered again when you open the note.": "Jika keluar, perubahan disimpan di perangkat ini dan ditawarkan lagi saat kamu membuka catatan.",
