  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "Gambar disimpan di samping catatan yang menampilkannya. Pilih ukuran maksimalnya, dan lihat ruang yang dipakai catatan dan gambar.",
  "Import and export": "Impor dan ekspor",
  "Imported": "Diimpor",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "Di ChatGPT, buka <b>Settings → Apps &amp; Connectors → Advanced settings</b> dan nyalakan <b>Developer mode</b>. Lalu pilih <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "Di Claude (web atau desktop), buka <b>Settings → Connectors</b> dan pilih <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "Di Claude Desktop, buka <b>Settings → Developer → Edit Config</b>. Di versi yang lebih baru, pilih <b>Claude</b> saja.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "Di Windsurf, buka <b>Settings → Cascade → MCP servers</b> dan pilih <b>View raw config</b>.",
