  "Interface": "Antarmuka",
  "Internet (tunnel)": "Internet (tunnel)",
  "Internet address (IP)": "Alamat internet (IP)",
  "It becomes your first rule.": "Ini jadi aturan pertamamu.",
  "It becomes {path}. Links to its notes keep working.": "Menjadi {path}. Tautan ke catatannya tetap berfungsi.",
  "It can change notes, but nothing lets it connect.": "Ia bisa mengubah catatan, tetapi tidak ada yang membuatnya bisa terhubung.",
  "It can search and read your notes, but not change them": "Ia bisa mencari dan membaca catatanmu, tetapi tidak bisa mengubahnya",
  "It can search, read and save your notes": "Ia bisa mencari, membaca, dan menyimpan catatanmu",
  "It can {list}.": "Ia bisa {list}.",
  "It cannot do anything yet": "Ia belum bisa melakukan apa pun",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "Ia punya kendali penuh: membaca dan mengubah catatan, serta bisa mengelola Memora dan agen lain",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Isinya {n} catatan. Berikutnya kamu pilih nasibnya: pindahkan ke folder lain, atau ke Sampah. Belum ada yang diubah.",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Isinya {n} catatan. Berikutnya kamu pilih nasibnya: pindahkan ke folder lain, atau ke Sampah. Belum ada yang diubah.",
  "It is added at the end, as rule {n}, so it is checked last.": "Ditambahkan di akhir sebagai aturan {n}, jadi dicek paling akhir.",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "Semuanya hilang saat kamu pergi, termasuk gambar. Perubahan pada catatanmu tetap tampil di Aktivitas dan Riwayat.",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "Kunci disimpan terkunci di server. Masukkan kata sandi Memora-mu dan tombol di bawah akan mengisinya untukmu.",
  "It is taking a while. Check the server, then reload this page.": "Agak lama. Periksa server, lalu muat ulang halaman ini.",
  "It leaves the Pinned list only; the folder itself stays where it is.": "Hanya keluar dari daftar Disematkan; foldernya tetap di tempatnya.",
  "It leaves the Pinned list only; the note itself stays where it is.": "Hanya keluar dari daftar Disematkan; catatannya tetap di tempatnya.",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "Mungkin sudah diganti nama, dipindah, atau dihapus. Catatan yang dihapus menunggu di Sampah.",
  "It moves; links to it are updated and pins follow.": "Catatan dipindah; tautan ke sana diperbarui dan sematan ikut.",
  "It must sign in again and is told why": "Harus masuk lagi dan diberi tahu alasannya",
  "It prints a one-time code. This page moves on by itself.": "Perintah ini menampilkan kode sekali pakai. Halaman ini akan lanjut sendiri.",
  "It reached Memora but did not finish. It often works on the next try.": "Permintaan sampai ke Memora tetapi tidak selesai. Biasanya berhasil di percobaan berikutnya.",
  "It reached Memora but did not finish: {error} It often works on the next try.": "Permintaan sampai ke Memora tetapi tidak selesai: {error} Biasanya berhasil di percobaan berikutnya.",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "Ia tampil dengan nama ini di Aktivitas, otak, dan graf. Namai sesuai perangkat jika kamu memakai {app} di lebih dari satu tempat, misalnya \"{example}\".",
  "It was shown when it was made. Make a new key to see one again.": "Ditampilkan saat dibuat. Buat key baru untuk melihatnya lagi.",
  "Italic": "Miring",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "API key dan modelnya dihapus. Chat tetap ada; chat yang memakai salah satu modelnya beralih ke default.",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "Kunci dan aksesnya tetap sama di setiap folder catatan. Hubungkan AI lain kapan saja.",
  "Its key is filled in on the next step": "Kuncinya diisi di langkah berikutnya",
  "Its key is refused until you turn it back on. Nothing is deleted.": "Key-nya ditolak sampai kamu menyalakannya lagi. Tidak ada yang dihapus.",
  "Its key is refused. Turn it on to let it connect again with the same key.": "Key-nya ditolak. Nyalakan agar bisa terhubung lagi dengan key yang sama.",
  "Its key stopped working. You can restore it until you reload the app.": "Key-nya berhenti berfungsi. Kamu bisa memulihkannya sampai aplikasi dimuat ulang.",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "Key-nya langsung berhenti berfungsi. Aktivitas lama tetap ada; kamu bisa memulihkannya sampai aplikasi dimuat ulang.",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "Kuncinya hanya ditampilkan sekali, saat dibuat. Kunci baru menggantikannya dan yang lama langsung berhenti berfungsi.",
  "Its notes are in its folders. You can also start one here.": "Catatannya ada di subfoldernya. Kamu juga bisa membuat satu di sini.",
  "Its numbers, timeline and export.": "Angka, linimasa, dan ekspornya.",
  "Its old folder is not known, so it goes to the top level": "Folder lamanya tidak diketahui, jadi masuk ke tingkat atas",
  "Its page": "Halamannya",
  "Its page shows how to connect it.": "Halamannya menunjukkan cara menghubungkannya.",
  "Its page: status, recent calls, access and settings.": "Halamannya: status, panggilan terbaru, akses, dan pengaturan.",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "Izinnya campuran khusus. Pilih tingkat untuk menggantinya, atau atur detailnya di Lanjutan.",
