  "Long chats, light": "Chat panjang tetap ringan",
  "Long enough. A few more characters make it stronger.": "Sudah cukup panjang. Tambah beberapa karakter agar lebih kuat.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Tugas yang panjang tampil sebagai checklist di atas kotak pesan: belum mulai, sedang jalan, selesai.",
  "Longest sign-in": "Masa masuk terlama",
