  "Look for tags that mean the same thing": "Cari tag yang artinya sama",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Telusuri proyek di folder ini dan simpan ke Memora: untuk apa, bagaimana dibangun, cara menjalankannya, keputusan teknis, dan hal lain yang layak diingat. Buat satu catatan per topik, di folder bernama sesuai proyek di dalam Projects.",
