  "Make an agent for each app or device you use. Each one gets its own key, so you can see what it does and turn it off on its own.": "Buat agen untuk setiap aplikasi atau perangkat yang kamu pakai. Masing-masing dapat key sendiri, jadi kamu bisa melihat apa yang dilakukannya dan mematikannya sendiri.",
