  "Medium": "Sedang",
  "Medium text": "Teks sedang",
  "Meet Mnemo, your notes agent": "Kenalan dengan Mnemo, agen catatanmu",
  "Memora address (MCP endpoint)": "Alamat Memora (endpoint MCP)",
  "Memora already uses this folder.": "Memora sudah memakai folder ini.",
  "Memora by Codrihub Tech": "Memora oleh Codrihub Tech",
  "Memora can save notes here": "Memora bisa menyimpan catatan di sini",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora mengecek folder dan meminta konfirmasi sebelum beralih. Tidak ada yang dipindah atau disalin, dan kamu bisa kembali ke sini. Pakai Docker? Gunakan folder yang di-mount ke container.",
  "Memora could not start.": "Memora gagal dimulai.",
  "Memora data folder": "Folder data Memora",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora mengecek dulu bahwa folder baru ada (atau bisa dibuat) dan bisa menyimpan catatan di sana. Kalau gagal, tidak ada yang berubah.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora mengecek dulu bahwa folder baru ada dan bisa menyimpan catatan di sana. Kalau gagal, tidak ada yang berubah.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora dalam bahasamu, Mnemo menunjukkan rencananya sambil bekerja, dan kamu yang menentukan apa yang boleh ia pakai dan lihat.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora adalah aplikasi catatan yang juga bisa dipakai aplikasi AI-mu. Kamu menulis di sini, mereka membaca dan menulis catatan yang sama, dan kamu selalu bisa melihat apa yang berubah.",
  "Memora is free and open source": "Memora gratis dan open source",
  "Memora is free and open source. A star helps others find it.": "Memora gratis dan open source. Bintang membantu orang lain menemukannya.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora adalah memori yang lebih maju: dibuat untuk mengingat apa yang Anda dan AI Anda pelajari, dan makin banyak mengingat makin sering dipakai.",
  "Memora is restarting": "Memora sedang dinyalakan ulang",
  "Memora is shut down": "Memora dimatikan",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora masih kosong. Hubungkan aplikasi AI, kirim satu prompt, dan ia menyimpan yang ia tahu tentangmu di sini, sebagai catatan yang bisa kamu baca, sunting, dan lihat di otak.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora menyimpan daftar tag-mu untuk disarankan saat mengetik. Segarkan kalau ada tag yang hilang atau usang.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora menyimpan setiap versi catatan jika folder vault adalah repositori git. Jalankan {cmd} sekali di folder vault (lihat Konfigurasi, “Version history” di dokumentasi); sejak itu setiap perubahan disimpan di sini.",
  "Memora keeps it in one place:": "Memora menyimpannya di satu tempat:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora menyimpan setiap catatan sebagai file Markdown biasa di mesin tempat ia berjalan. Tidak ada yang terkunci: buka file-nya di editor apa pun, cadangkan, atau simpan di Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora memakai MCP lewat streamable HTTP. Aplikasi mengirim kunci di header <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora berhenti di mesin tempatnya berjalan. Catatanmu tetap aman di disk.",
  "Memora version": "Versi Memora",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} tersedia. Server ini menjalankan v{current}.",
  "Memora, open Overview": "Memora, buka Ringkasan",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: vault catatan yang kamu host sendiri, dengan agen yang merapikannya.",
  "Memory used: {used} of {win}": "Memori terpakai: {used} dari {win}",
  "Mentioned in": "Disebut di",
  "Mentions": "Sebutan",
  "Menus, tidied": "Menu, dirapikan",
