  "Messaged {agent}": "Mengirim pesan ke {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Pesan dan kotak pesan sejajar persis di setiap lebar, pemilih model punya permukaannya sendiri, fleeting chat pas di ponsel, dan pilihan pertanyaan tidak bergeser saat diketuk.",
  "Middle-drag": "Seret-tengah",
  "Midnight": "Tengah malam",
  "Minimap": "Peta mini",
  "Minimap: click or drag to move the view": "Peta mini: klik atau seret untuk menggeser tampilan",
  "Mist": "Kabut",
  "Mnemo (AI agent)": "Mnemo (agen AI)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo dan agen bisa melakukan apa pun di papan seperti kamu, lewat MCP, di balik empat sakelar izin Kanban yang mengikuti Tanya dulu, Otomatis, dan Hanya baca.",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Tombol Mnemo disembunyikan. Tampilkan lagi dari Lainnya, Tampilkan tombol Mnemo.",
  "Mnemo goes on without sub-agents": "Mnemo lanjut tanpa sub-agen",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo belum punya model: tambahkan penyedia dan modelnya di Pengaturan, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo sudah ada di dalam Memora. Hubungkan kunci AI-mu sendiri, lalu minta dengan bahasa sehari-hari: ia mencari, menulis, memberi tag, menautkan, dan merapikan catatan untukmu.",
  "Mnemo is still answering in this chat": "Mnemo masih menjawab di chat ini",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo adalah agen bawaan Memora. Hubungkan kunci AI-mu sendiri lalu minta dengan bahasa sehari-hari: ia menjaga catatanmu tetap rapi selagi aplikasi lain memakainya.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo menyimpan maksimal {n} penyedia; hapus satu dulu",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo mengelola sub-agennya, menyimpan rencananya bersama chat, dan chat pas di setiap layar.",
  "Mnemo runs its sub-agents": "Mnemo mengatur sub-agennya",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo berhenti setelah {n} langkah; ketik \"lanjut\" untuk meneruskan.",
  "Mnemo's plan, live": "Rencana Mnemo, langsung",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "Pertanyaan Mnemo punya bagiannya sendiri, jawabannya di bawah sebagai baris yang tinggal diketuk, sebanyak yang dibutuhkan pertanyaannya.",
  "Mnemo, your notes agent": "Mnemo, agen catatanmu",
