  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Tidak dilakukan: Mnemo dalam mode Tanya dulu, jadi perubahan menunggu persetujuanmu. Mnemo akan bertanya dulu, lalu mengubah setelah kamu setuju.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Tidak dilakukan: Mnemo dalam mode Hanya baca, jadi catatan tidak diubah. Mnemo menyebutkan apa yang akan diubah; kamu bisa beralih ke Tanya dulu atau Otomatis di chat.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Tidak dilakukan: chat dalam mode Tanya dulu, jadi sub-agen tidak bisa mengubah catatan. Ia menyebutkan apa yang perlu diubah; Mnemo akan bertanya padamu.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Tidak dilakukan: {tool} dimatikan untuk Mnemo (Pengaturan, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Tidak dilakukan: {tool} dimatikan untuk sub-agen (Pengaturan, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "Belum selesai: balasan ini dihentikan sebelum tool selesai.",
  "Not found": "Tidak ditemukan",
