  "Not started: \"{name}\" fits more than one model or none exactly. Close ones: {list}. Ask the owner which, or give the exact id.": "Tidak dimulai: \"{name}\" cocok dengan lebih dari satu model atau tidak ada yang persis. Yang mirip: {list}. Tanyakan pemilik yang mana, atau berikan id yang tepat.",
  "Not started: there is no model \"{name}\" here. Tell the owner, or leave model out to use their default model.": "Tidak dimulai: tidak ada model \"{name}\" di sini. Beri tahu pemilik, atau kosongkan model untuk memakai model bawaan.",
  "Not sure it is on? Ask {app}: “{question}”": "Tidak yakin sudah aktif? Tanyakan ke {app}: “{question}”",
