  "Notes": "Catatan",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "Catatan dan papan memakai satu bingkai halaman dengan jarak yang sama di ponsel, tablet, dan desktop, dan tautan di bagian bawah catatan tampil rapi seragam dan bisa dilipat.",
  "Notes and boards, connected": "Catatan dan papan, kini terhubung",
  "Notes and images in the notes folder.": "Catatan dan gambar di folder catatan.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Catatan dan tautan di antaranya tampil di sini sebagai peta. Panduan menunjukkan cara meminta AI menyimpan pengetahuannya di sini, atau tulis catatan sendiri.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Catatan muncul saat AI menyimpannya dan menyalakan otak. Halaman ini berubah jadi dasbor saat catatan pertama tiba.",
  "Notes are not a password manager.": "Catatan bukan pengelola kata sandi.",
  "Notes changed in the app or in the folder": "Catatan yang diubah di aplikasi atau di folder",
  "Notes folder": "Folder catatan",
  "Notes folder switched": "Folder catatan diganti",
  "Notes from {name}": "Catatan dari {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Catatan berformat Obsidian Kanban terbuka sebagai papan. Seret kartu dan kolom pakai mouse atau jari, dan setiap perubahan masuk ke riwayat catatan.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Catatan di folder saat ini tidak dipindah, disalin, atau dihapus. Kamu bisa kembali ke sini kapan saja.",
  "Notes inside a folder": "Catatan di dalam folder",
  "Notes it found": "Catatan yang ditemukan",
  "Notes it saved": "Catatan yang disimpannya",
  "Notes must carry": "Catatan harus punya",
  "Notes tagged #{tag}": "Catatan dengan tag #{tag}",
  "Notes that carry at least one tag": "Catatan yang punya minimal satu tag",
  "Notes that carry every tag": "Catatan yang punya semua tag",
  "Notes that link nowhere and are linked from nowhere.": "Catatan yang tidak menaut ke mana pun dan tidak ditaut dari mana pun.",
  "Notes touched": "Catatan disentuh",
  "Notes with a tag; the start of the tag is enough": "Catatan dengan tag; awal tag saja cukup",
  "Notes you delete wait here, so you can bring them back.": "Catatan yang kamu hapus menunggu di sini, jadi bisa dikembalikan.",
  "Notes you or your AIs write show up here, newest first.": "Catatan yang ditulis kamu atau AI-mu muncul di sini, terbaru dulu.",
  "Notes, folders and images in this chat": "Catatan, folder, dan gambar di chat ini",
  "Nothing deleted": "Tidak ada yang dihapus",
  "Nothing else in the last 24 hours.": "Tidak ada lagi dalam 24 jam terakhir.",
  "Nothing from {name} in the last 24 hours.": "Tidak ada dari {name} dalam 24 jam terakhir.",
  "Nothing here": "Tidak ada apa-apa",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Belum ada yang disembunyikan: centang agen yang ingin disembunyikan. Saat ini semua {n} agen bisa melihatnya.",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Belum ada yang disembunyikan: centang agen yang ingin disembunyikan. Saat ini satu-satunya agen bisa melihatnya.",
  "Nothing in 24h": "Tidak ada dalam 24 jam",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Tidak ada di nama catatan, folder, atau isi, dan tidak ada ejaan yang mirip. Coba lebih sedikit huruf, ejaan lain, atau kata dari dalam catatan.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "Tidak ada dalam 24 jam terakhir. Apa yang dilakukan AI-mu muncul di sini saat terjadi.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "Tidak ada di log dengan nama “{name}”. Menampilkan semua aktivitas.",
  "Nothing in this range": "Tidak ada di rentang ini",
  "Nothing in your chats says “{query}”.": "Tidak ada chat yang menyebut “{query}”.",
  "Nothing is allowed. Turn something on, or pause the agent instead.": "Tidak ada yang diizinkan. Nyalakan sesuatu, atau jeda agennya saja.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "Tidak ada yang hilang: teks saat ini tetap di riwayat sebagai v{n}, jadi kamu bisa kembali kapan saja.",
  "Nothing links here yet.": "Belum ada yang menaut ke sini.",
  "Nothing matches": "Tidak ada yang cocok",
