  "Nothing matches “{q}”.": "Tidak ada yang cocok dengan “{q}”.",
  "Nothing matches “{q}”. Maybe you meant one of these:": "Tidak ada yang cocok dengan “{q}”. Mungkin maksud Anda salah satu ini:",
  "Nothing matches.": "Tidak ada yang cocok.",
  "Nothing needs you right now.": "Tidak ada yang butuh kamu saat ini.",
