  "Offline · Memora": "Offline · Memora",
  "Offline, retrying": "Offline, mencoba lagi",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Gemini CLI lama tanpa <code>gemini mcp add</code>: tambahkan server ke <code>~/.gemini/settings.json</code> di bawah <code>mcpServers</code>, dengan <code>httpUrl</code> dan header yang sama.",
  "Older changes stay in History.": "Perubahan lama tetap tersimpan di Riwayat.",
  "Older messages were left out to fit the model's context.": "Pesan lama dilewati agar muat di konteks model.",
  "Older than 30 days": "Lebih dari 30 hari",
  "Older than 7 days": "Lebih dari 7 hari",
  "Older than 90 days": "Lebih dari 90 hari",
  "Older versions of a note: read, compare, restore, and the trash.": "Versi lama catatan: baca, bandingkan, pulihkan, dan sampah.",
  "Oldest entry": "Entri terlama",
  "On": "Nyala",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "Di desktop, seret tepi daftar chat atau panel samping untuk melebarkan atau menyempitkannya. Masing-masing punya lebar minimum dan mengingat lebarnya.",
  "On hover": "Saat disorot",
  "On its avatar, its sparks in the brain and every activity row.": "Di avatarnya, percikannya di otak, dan setiap baris aktivitas.",
  "On this page": "Di halaman ini",
  "On: tap to switch off": "Aktif: ketuk untuk mematikan",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "Aktif: {mnemo} mencatat apa yang ditangkapnya di chat. Mati: hanya yang kamu tambahkan di sini. Langsung tersimpan.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Setelah terpasang, aplikasi punya ikon sendiri, terbuka layar penuh, dan tetap bisa dibuka saat jaringan putus.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Setelah terhubung, tempel ini ke chat baru di aplikasi itu. Ini menyuruh AI menyimpan yang ia tahu ke Memora.",
  "Once its app is set up, every call shows up here as it happens.": "Setelah aplikasinya diatur, setiap panggilan muncul di sini saat terjadi.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Setelah {name} terhubung, semua yang dibaca, ditulis, dan dicarinya muncul di sini secara langsung.",
  "One address": "Satu alamat",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Satu agen per aplikasi atau perangkat: key sendiri, nama sendiri di Aktivitas, bisa dimatikan sendiri.",
  "One click": "Sekali klik",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Satu perangkat atau koneksi, misalnya 203.0.113.7. Cari \"what is my IP\" untuk melihat punyamu.",
  "One device or connection.": "Satu perangkat atau koneksi.",
  "One folder of notes that you and every connected AI share.": "Satu folder catatan yang dipakai bersama oleh kamu dan setiap AI yang terhubung.",
  "One is hidden by the folder rule.": "Satu disembunyikan oleh aturan folder.",
  "One key per agent, its own permissions.": "Satu key per agen, dengan izin sendiri.",
  "One last step": "Satu langkah lagi",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Satu memori yang dibaca dan ditulis semua agen, dan kamu bisa melihat, mengedit, dan menghubungkan semuanya.",
  "One memory for every AI": "Satu memori untuk setiap AI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "Satu catatan menampilkan gambar ini; di sana akan tampil sebagai hilang. Riwayat versi tetap menyimpannya.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Satu per baris. Muncul di antara saran pada chat baru, ditandai Milikmu, dan tetap ada sampai kamu mengubahnya.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Satu memori pribadi yang Anda bagi dengan aplikasi AI Anda, jadi tak ada yang perlu dijelaskan dua kali.",
  "One set of notes for every AI app": "Satu kumpulan catatan untuk semua aplikasi AI",
  "Online": "Online",
  "Only PNG, JPEG, WebP and GIF images can be added": "Hanya gambar PNG, JPEG, WebP, dan GIF yang bisa ditambahkan",
  "Only in the current version": "Hanya di versi saat ini",
  "Only in version {n}": "Hanya di versi {n}",
  "Only letters, digits and - _ / . can be used.": "Hanya huruf, angka, dan - _ / . yang boleh dipakai.",
  "Only looks at notes; changes nothing.": "Hanya melihat catatan; tidak mengubah apa pun.",
  "Only looks things up and never writes. For agents with a read-only key.": "Hanya mencari dan tidak pernah menulis. Untuk agen dengan key hanya-baca.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Hanya gambar di pesan terbarumu yang dikirim ke model gambar, dan kamu cukup diberi tahu lewat toast singkat.",
  "Only reads and answers; never changes notes": "Hanya membaca dan menjawab; tak pernah mengubah catatan",
  "Only the agents you pick. New agents can’t see it.": "Hanya agen yang kamu pilih. Agen baru tidak bisa melihatnya.",
  "Only the first rule that fits a request counts.": "Hanya aturan pertama yang cocok yang berlaku.",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "Hanya pertanyaan terbaru yang dimuat dulu; yang lebih lama muncul saat kamu scroll ke atas atau lompat lewat timeline.",
  "Only the ones I pick": "Hanya yang kupilih",
