  "Operations": "Operasional",
  "Optional. A few words on who you are, what you work on, how you like answers. {mnemo} keeps them and you can change them any time in Settings.": "Opsional. Beberapa kata tentang siapa kamu, apa yang kamu kerjakan, dan jawaban seperti apa yang kamu suka. {mnemo} menyimpannya dan kamu bisa mengubahnya kapan saja di Pengaturan.",
