  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "Tempel di terminal lalu tekan <kbd>Enter</kbd>, kemudian jalankan Codex di terminal yang sama.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Tempel di terminal lalu tekan <kbd>Enter</kbd>. Kemudian jalankan Claude Code, atau mulai ulang: Memora dimuat otomatis.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "Tempel di terminal lalu tekan <kbd>Enter</kbd>. Kemudian jalankan atau mulai ulang Gemini CLI, dan ketik <code>/mcp</code> untuk melihat Memora.",
  "Paste it into the app where it asks for a key.": "Tempel ke aplikasi di tempat ia meminta kunci.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Tempel ke file dan simpan, lalu tekan <b>Refresh</b>. Memora muncul di daftar.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "Tempel ke file, simpan, lalu mulai ulang Claude Desktop. Ini memerlukan Node.js di komputer ini.",
  "Paste it into {app}": "Tempel ke {app}",
