  "Paste these once where {app} reads its standing instructions, so it uses Memora in every conversation, not only when asked.": "Tempel sekali di tempat {app} membaca instruksi tetapnya, agar ia memakai Memora di setiap percakapan, bukan hanya saat diminta.",
