  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Simpan ke Memora yang pernah kuceritakan tentang kehidupan pribadiku: minat, kebiasaan, tujuan, orang-orang yang penting bagiku, dan hal-hal yang kupedulikan. Taruh catatan ini di folder bernama Private, satu catatan per topik, dan tautkan catatan yang berkaitan. Jangan pernah menyimpan kata sandi, nomor kartu, atau rahasia lain. Setelah selesai, beri tahu aku apa saja yang kamu simpan.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Simpan ke Memora yang kamu tahu tentang pekerjaanku: peranku, timku, proyek yang sedang kujalani dan statusnya, serta keputusan yang kami ambil. Buat satu catatan per proyek atau topik dan tautkan satu sama lain.",
