  "This note is removed from the vault for good, with its text, tags and links. Every earlier version is erased from the version history too, so no one, agents included, can read it again.": "Catatan ini dihapus permanen dari vault, beserta teks, tag, dan tautannya. Semua versi sebelumnya juga dihapus dari riwayat versi, jadi tidak ada yang bisa membacanya lagi, termasuk agen.",
