  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} hanya bekerja di catatanmu. Setiap perubahan tampil di Aktivitas dan bisa dibatalkan dari Riwayat.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} membaca vault-mu di chat baru dan menyimpan yang dipelajarinya di sini.",
  "{mnemo} settings saved": "Pengaturan {mnemo} disimpan",
  "{mnemo} settings: models and keys": "Pengaturan {mnemo}: model dan kunci",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} menjalankan sub-agen sendiri saat tugas mudah dipecah; tidak ada yang perlu diatur. Sub-agen memakai model default-mu, lalu model cadangan, kecuali kamu menyebut model di chat. Pantau mereka, dan ganti modelnya, di Agen di kanan atas chat. Mereka memakai token sendiri, jadi dalam Tanya dulu {mnemo} bertanya dan menyebut kira-kira berapa banyak; dalam Otomatis mereka langsung berjalan. Langsung tersimpan.",
