  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} tidak bisa melihat gambar; ia hanya menerima namanya. Atur model yang bisa membaca gambar di Pengaturan agar gambar bisa dilihat.",
