  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} tidak bisa membaca gambar, jadi hanya menerima namanya. Atur model yang bisa membaca gambar, atau ganti model chat ini.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} tidak bisa membaca gambar, jadi hanya menerima namanya. Atur model yang bisa membaca gambar, atau ganti model chat ini.",
